// ── Frontend-only — no Rust counterpart ────────────────────────────
// These describe React state, form input, or display-side enums that
// never cross the invoke boundary.

/** Narrowing of `LogEvent.tag` — Rust ships it as `string`, but only
 *  ever emits one of these five values, so we narrow at the boundary. */
export type LogTag = "info" | "ok" | "warn" | "err" | "muxer";

/** Boundary narrowing for an incoming `LogEvent.tag`. Returns the
 *  matching `LogTag` literal, or `"info"` for unknown strings (never
 *  expected — defensive against a Rust-side enum addition). */
export function asLogTag(s: string): LogTag {
  return (s === "ok" || s === "warn" || s === "err" || s === "muxer")
    ? s
    : "info";
}

export type AppStatus =
  | "empty"
  | "fetching"
  | "loaded"
  | "exporting"
  | "success"
  | "error";

export type FormatId = "4k" | "1080" | "720" | "audio";

export type ExportOpts = {
  inTc: string;
  outTc: string;
  filename: string;
  folder: string | null;
  format: FormatId;
  captions: boolean;
  reencode: boolean;
};

export type RecentClip = {
  id: string;
  title: string;
  path: string;
  dur: string;
  when: number; // epoch ms
  thumbnail: string | null;
  /** Source identity (webpage URL or local file path). Grouping in the
   *  sidebar keys on this — titles are display-only and can collide
   *  (review fix). Optional: legacy entries fall back to the title. */
  source?: string;
};


export type QueueStatus = "queued" | "running" | "done" | "error";

/** Where a queued clip reads its media from — captured at ADD time so the
 *  queue runner never depends on the currently-loaded source (the queue
 *  survives source switches; mixed web+local queues just work). */
export type QueueSource =
  | { kind: "web"; url: string }
  | { kind: "file"; path: string };

export type QueuedClip = {
  id: string;
  source: QueueSource;
  /** Source fps at add time — ALL frames→seconds/tc math for this item must
   *  use it, never the live player fps (which may belong to another source). */
  fps: number;
  /** Title + thumbnail at add time — recents attribution for mixed/stale queues. */
  title: string;
  thumbnail: string | null;
  inFrames: number;
  outFrames: number;
  filename: string;
  format: FormatId;
  /** Web-only (yt-dlp re-encode); local items set false — mediabunny decides
   *  passthrough vs re-encode itself. */
  reencode: boolean;
  /** Web-only (yt-dlp subtitles); always false for file items. */
  captions: boolean;
  status: QueueStatus;
  path?: string;
  error?: string;
};

export type SourceKind = "youtube" | "file";

export type ClientLog = {
  id: number;
  ts: string;          // HH:MM:SS
  tag: LogTag;
  source: string;      // e.g. "yt-dlp", "ffmpeg", "probe", "ok", "warn"
  message: string;
};

/**
 * The in-progress comment range drawn on the timeline.
 *
 * Two shapes on purpose. `live` carries only the ANCHOR — the edge the user
 * has marked — and the band's other end is wherever the playhead is right
 * now, read by the timeline itself. That is what keeps a scrub from
 * re-rendering the App tree at source fps while someone hunts the out point.
 * Once both ends are marked the band is fixed and needs no clock at all.
 */
export type ReviewRangeDraft =
  | { live: true; anchor: number; color: string }
  | { live: false; start: number; end: number; color: string };
